 "content": "def transform(grid):
    """Fill the interiors of triangles whose two sides are diagonal rays of a marker color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for dr in (-1, 1):
                depth = 1
                while True:
                    rr = r + dr * depth
                    left, right = c - depth, c + depth
                    if not (0 <= rr < h and 0 <= left < w and right < w):
                        break
                    if grid[rr][left] != color or grid[rr][right] != color:
                        break
                    for cc in range(left + 1, right):
                        if out[rr][cc] == 0:
